sys_variable_value.value:
// ATF injects assertEqual, steps, outputs, stepResult and an enclosing try block - bare body.
// steps(SYS_ID) is ATF's injected accessor for an earlier step's outputs. GEM {{ step[...] }}
// templates are NOT substituted in a script body, so the sys_id must be passed literally.
var orderId = steps("a3f959fa54d44f1bb9df2327ee4eb3bb").record_id;
if (!orderId || ('' + orderId).length !== 32) {
    throw new Error('unresolved step reference for orderId: ' + orderId);
}
var costId = steps("9bd8d08fa2e646edaee245e10e7f8692").record_id;
if (!costId || ('' + costId).length !== 32) {
    throw new Error('unresolved step reference for costId: ' + costId);
}
function num(v) { return parseFloat(v) || 0; }

var pc = new GlideRecord('x_2298436_snackf_0_prod_cost');
if (!pc.get(costId)) throw new Error('cost sheet not found');

// Rebuild material cost from the consumption rows and the live unit costs,
// so the expected figure comes from data, not from a literal in the test.
var expectedMaterial = 0, packagingLines = 0, blankCostLines = 0;
var mc = new GlideRecord('x_2298436_snackf_0_material_consumption');
mc.addQuery('production_order', orderId);
mc.query();
while (mc.next()) {
    if (mc.getValue('item_type') === 'raw_material') {
        var rm = new GlideRecord('x_2298436_snackf_0_raw_material');
        if (rm.get(mc.getValue('raw_material'))) {
            expectedMaterial += num(mc.getValue('actual_quantity')) * num(rm.getValue('unit_cost'));
        }
    } else if (mc.getValue('item_type') === 'packaging_material') {
        packagingLines++;
        var pm = new GlideRecord('x_2298436_snackf_0_packaging_material');
        if (pm.get(mc.getValue('packaging_material'))) {
            var uc = pm.getValue('unit_cost');
            if (uc === null || uc === '' || uc === undefined) blankCostLines++;
        }
    }
}
expectedMaterial = Math.round(expectedMaterial * 100) / 100;
assertEqual({ name: 'material cost rebuilt from consumption x live unit costs', shouldbe: expectedMaterial, value: num(pc.getValue('material_cost')) });

// Packaging must be excluded, not guessed, while any unit cost is blank.
assertEqual({ name: 'at least one packaging line has a blank unit cost', shouldbe: true, value: blankCostLines > 0 });
assertEqual({ name: 'packaging cost excluded (0) while unit cost blank', shouldbe: 0, value: num(pc.getValue('packaging_cost')) });
// getValue() on a boolean column returns the stored '0'/'1', not 'false'/'true'. The
// recordValidation step above asserts the same fact via the encoded-query form
// 'packaging_cost_complete=false', which the platform maps to 0 - that step passed.
assertEqual({ name: 'packaging_cost_complete is false', shouldbe: '0', value: '' + pc.getValue('packaging_cost_complete') });

// Total and per-packet recomputed from the sheet's own parts.
var expectedTotal = Math.round((num(pc.getValue('material_cost')) + num(pc.getValue('packaging_cost')) +
    num(pc.getValue('labour_cost')) + num(pc.getValue('overhead_cost'))) * 100) / 100;
assertEqual({ name: 'total = material + packaging + labour + overhead', shouldbe: expectedTotal, value: num(pc.getValue('total_cost')) });

var good = num(pc.getValue('good_quantity'));
assertEqual({ name: 'good quantity rolled up from the output record', shouldbe: 95, value: good });

// cost_per_packet is a 2-decimal column, so compare within half a cent.
var expectedPerPacket = expectedTotal / good;
var actualPerPacket = num(pc.getValue('cost_per_packet'));
assertEqual({
    name: 'cost per packet = total / good (within column precision)',
    shouldbe: true,
    value: Math.abs(actualPerPacket - expectedPerPacket) < 0.005,
});

// Consumption must never post to the stock ledger.
var led = new GlideAggregate('x_2298436_snackf_0_stock_transaction');
led.addQuery('production_order', orderId);
led.addAggregate('COUNT');
led.query();
var ledRows = led.next() ? parseInt(led.getAggregate('COUNT'), 10) : 0;
assertEqual({ name: 'consumption posted no stock ledger rows', shouldbe: 0, value: ledRows });

stepResult.setOutputMessage(
    'material=' + pc.getValue('material_cost') + ' packaging=' + pc.getValue('packaging_cost') +
    ' total=' + pc.getValue('total_cost') + ' good=' + good +
    ' per_packet=' + actualPerPacket + ' (exact ' + expectedPerPacket.toFixed(4) + ')' +
    ' packaging_complete=' + pc.getValue('packaging_cost_complete') +
    ' packaging_lines=' + packagingLines + ' blank_cost_lines=' + blankCostLines
);
